package core

import (
	"bytes"
	"crypto/sha256"
	"fmt"
	"sync"
	"testing"
)

func TestSSUDPTableConcurrentWireCompatibility(t *testing.T) {
	cfg := defaults()
	cfg.Cipher, cfg.Password = "table", "synthetic server secret"
	codec, err := newSSUDP(cfg)
	if err != nil {
		t.Fatal(err)
	}
	address, _ := Address("127.0.0.1", 443)
	body := make([]byte, 256)
	for i := range body {
		body[i] = byte(i)
	}
	// Golden digest generated by the independent Python stable-sort/translate
	// oracle in test_support_additions.py, including the seven-byte address.
	const golden = "173921da2f4651b1a0630a1420d5bbaf18fd7050f9bfccb2360650071ddcd95c"
	errors := make(chan error, 32)
	var workers sync.WaitGroup
	for i := 0; i < 32; i++ {
		workers.Add(1)
		go func() {
			defer workers.Done()
			for packet := 0; packet < 16; packet++ {
				wire, err := codec.encode(Datagram{address, body})
				if err != nil {
					errors <- err
					return
				}
				if fmt.Sprintf("%x", sha256.Sum256(wire)) != golden {
					errors <- fmt.Errorf("table wire differs from independent oracle")
					return
				}
				got, err := codec.decode(wire)
				if err != nil || !bytes.Equal(got.Address, address) || !bytes.Equal(got.Payload, body) {
					errors <- fmt.Errorf("shared table decode: %v", err)
					return
				}
			}
		}()
	}
	workers.Wait()
	close(errors)
	for err := range errors {
		t.Error(err)
	}
}
